mapper.insert:

declare
  v_lote_id         lotes_sims.lote_id%type := 0;
  v_lote_in_table   lotes_sims.lote_id%type := 0;
  v_imsi_in_table   sims.sim_imsi%type := 0;
  v_imsi_generated  sims.sim_imsi%type := 0;
  v_iccid_generated sims.sim_iccid%type;
begin
  while v_lote_in_table = v_lote_id loop
    select lote_id_seq.nextval into v_lote_id from dual;
    begin
      select lote_id into v_lote_in_table from lotes_sims where lote_id = v_lote_id;
    exception
      when no_data_found then null;
    end;
  end loop;
  while v_imsi_in_table = v_imsi_generated loop
    select trunc(dbms_random.value(100000000000000, 999999999999999)) into v_imsi_generated from dual;
    select v_imsi_generated || trunc(dbms_random.value(1000, 9999)) into v_iccid_generated from dual;
    begin
      select sim_imsi into v_imsi_in_table from sims where sim_imsi = v_imsi_generated;
    exception
      when no_data_found then null;
    end;
  end loop;
  insert into lotes_sims
    (lote_id, lote_quant, lote_sim_type, lote_subscription_type, lote_electrical_profile,
     lote_graphic_profile, lote_transport_key, lote_transport_kappli, lote_po_ref_number,
     lote_imsi_start_number, lote_iccid_start_number, lote_supplier, lote_technology,
     lote_country, lote_proc_date, lote_file_name)
  values
    (v_lote_id, 10000, 'PLUG-IN', 0, '01.01C', '01.01', 1, 1, 'S/N',
     v_imsi_generated, v_iccid_generated, 31, 'USIM 256K', #{country}, sysdate, #{subId});
  insert into sims (sim_lote_id, sim_pro_id, sim_imsi, sim_iccid, sim_msisdn)
  values (v_lote_id, '20310040', v_imsi_generated, v_iccid_generated || 'F', #{subId});
  insert into sim_histories (sih_sim_iccid, sih_chs_id, sih_start_date, sih_end_date, sih_usr_id)
  values (v_iccid_generated || 'F', '217', sysdate, null, 'WEB');
end;


declare
  v_existe          number(1);
  v_nim             cellulars.clu_cellular_number%type := #{cellularNumber};
  v_iccid           sims.sim_iccid%type := #{iccid};
  v_hexa            electronical_serial_numbers.esn_hexa%type := trim(trailing 'F' from #{iccid});
  v_activation_date service_request_forms.srf_activation_date%type := sysdate;
  v_pro_id          sims.sim_pro_id%type;
  v_imsi            sims.sim_imsi%type;
  v_esc_start_date  esn_cellulars.esc_start_date%type;
begin
  select sim_pro_id, sim_imsi into v_pro_id, v_imsi from sims where sim_iccid = v_iccid;
  begin
    insert into electronical_serial_numbers (esn_hexa, financial_flag, esn_pro_id)
    values (v_hexa, 'N', v_pro_id);
  exception
    when dup_val_on_index then
      update electronical_serial_numbers set financial_flag = 'N', esn_pro_id = v_pro_id where esn_hexa = v_hexa;
  end;
  begin
    select 1 into v_existe from esn_cellulars where esc_clu_cellular_number = v_nim and esc_end_date is null;
  exception
    when no_data_found then v_existe := 0;
  end;
  if v_existe = 1 then
    update esn_cellulars set esc_esn_hexa = v_hexa where esc_clu_cellular_number = v_nim and esc_end_date is null;
  else
    insert into esn_cellulars
      (esc_esn_hexa, esc_clu_cellular_number, esc_start_date, esc_est_id, esc_est_own_id, esc_dlr_id, esc_usr_id)
    values
      (v_hexa, v_nim, sysdate, 'DIST', 'CTI', #{dealerId}, 'WEB');
  end if;
  insert into cellular_terminals
    (cet_id, cet_sim_iccid, cet_clu_cellular_number, cet_pro_id, cet_imei, cet_est_id, cet_est_own_id, cet_start_date)
  values
    (#{cetId}, v_hexa, v_nim, '20300001', '999999999999994', 'DIST', 'CTI', v_activation_date);
  insert into cellular_terminal_status (cts_cet_id, cts_chs_id, cts_usr_id, cts_start_date)
  values (#{cetId}, 221, 'WEB', v_activation_date);
  update sims set sim_msisdn = #{subId} where sim_iccid = v_iccid;
  select esc_start_date into v_esc_start_date from esn_cellulars where esc_clu_cellular_number = v_nim and esc_end_date is null;
  update sim_histories set sih_end_date = v_esc_start_date where sih_sim_iccid = v_iccid and sih_chs_id = '217' and sih_end_date is null;
  insert into sim_histories (sih_sim_iccid, sih_chs_id, sih_start_date, sih_usr_id)
  values (v_iccid, '218', v_esc_start_date, 'WEB');
end;

mapper.delete:

declare
  v_linea cellulars.clu_cellular_number%type := #{cellularNumber};
  v_user updates.upd_usr_id%type := upper(#{user});
begin
  delete from applied_tools where apt_clu_cellular_number = v_linea;
  delete from cellular_call_restrictions where ccr_clu_cellular_number = v_linea;
  delete from cellular_packages where cpk_clu_cellular_number = v_linea;
  delete from service_status where sst_clu_cellular_number = v_linea;
  delete from cellular_plans where cpl_clu_cellular_number = v_linea;
  delete from esn_cellulars where esc_clu_cellular_number = v_linea;
  delete from cellulars where clu_cellular_number = v_linea;
  delete from activation_ranges where acr_starting_range = v_linea;
  delete from cellular_business_histories where cbh_clu_cellular_number = v_linea;
  delete from cellular_accounts where cac_clu_cellular_number = v_linea;
  delete from cellular_services where cese_clu_cellular_number = v_linea;
  delete from updates where upd_table_name in ('ACCOUNTS', 'CELLULARS') and upd_usr_id = v_user;
  delete from gsm_wap_interfaces where gwi_clu_bill_number = v_linea;
  delete from credit_limit_assignments where clas_clu_cellular_number = v_linea;
  delete from planes_borrados where celular = v_linea;
end;
